SELECT s.Name, s.Song_release_year
FROM singer s
WHERE s.Age = (SELECT MIN(Age) FROM singer);

SELECT s.Name
FROM stadium s
WHERE s.Stadium_ID NOT IN (
    SELECT DISTINCT Stadium_ID
    FROM singer_in_concert
);

SELECT c.Continent, COUNT(*) as Count
FROM countries c
GROUP BY c.Continent;

SELECT COUNT(*) FROM car_makers
WHERE car_makers.Country = (SELECT CountryName FROM countries WHERE countries.Continent = (SELECT ContId FROM continents WHERE continents.Continent = 'europe'))
AND car_makers.Country = 2;

SELECT car_makers.Maker, car_names.Model
FROM car_makers
JOIN car_names ON car_makers.Id = car_names.MakeId;

SELECT COUNT(*) 
FROM car_makers 
WHERE Maker = 'American Motor Company' AND FullName = 'American Motor Company';

SELECT AirportCode, AirportName
FROM airports
WHERE City = 'Anthony ';

SELECT DISTINCT SourceAirport
FROM flights
WHERE SourceAirport NOT IN (SELECT AirportCode FROM airports);

SELECT Template_Type_Code
FROM Ref_Template_Types
WHERE Template_Type_Code NOT IN (
    SELECT Template_Type_Code
    FROM Templates
);

SELECT p.Document_ID, p.Paragraph_Text
FROM Paragraphs p
WHERE p.Paragraph_Text IN ('Brazil', 'Ireland');

SELECT Name
FROM teacher
WHERE Hometown != 'Little Lever Urban District';

SELECT SUM(Num_of_Ticket) AS Total_Ticket_Expense
FROM visit
WHERE visitor_ID IN (
    SELECT ID FROM visitor
    WHERE Level_of_membership = 1
);

SELECT T."Episode", T."Rating"
FROM "TV_series" T
ORDER BY T."Rating" ASC;

SELECT AVG(LifeExpectancy) AS averageLifeExpectancy
FROM country
WHERE Code IN (
    SELECT Code FROM country
    WHERE Region = 'Central Africa' OR Region = 'Africa'
) AND GovernmentForm = 'Republic';

SELECT c.Name, c.IndepYear, c.SurfaceArea
FROM country c
WHERE c.Population = (SELECT MIN(Population) FROM country);
